#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: C1 supervised measurement session (KENN_PLAN.md, C1).
#
# Run on the owner's M3/16 GB Mac from any directory:
#   products/kenn/tooling/scripts/c1_supervised_session.sh
# It only reads Live (KENN_LIVE_BACKEND=fake everywhere) and never starts,
# stops or restarts the companion: the owner does that, because how it is
# launched on that Mac is not recorded in the repo. Receipts land in a
# git-ignored .runtime/ folder; nothing here commits or uploads anything.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

KENN_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
PYTHON="${PYTHON:-python3}"
MODEL="${KENN_C1_MODEL:-qwen3:4b-instruct-2507-q4_K_M}"
OLLAMA="${OLLAMA_HOST_URL:-http://127.0.0.1:11434}"
ENDPOINT="${KENN_ENDPOINT:-http://127.0.0.1:8090}"
OUT="${KENN_C1_OUT:-$KENN_ROOT/.runtime/c1-$(date +%Y-%m-%d)}"
mkdir -p "$OUT"
# Answers given in this session are kept here so a re-run after Ctrl-C offers them back.
ENV_FILE="$OUT/session.env"

# The production answer path with the response cache off. KENN_LLM_CACHE=0 matters: with it on, a rerun replays
# earlier answers at ~0.1 s with no model call (measured 1 Oct 2026), and the receipt cannot undo that afterwards.
STREAM_ENV=(KENN_LIVE_BACKEND=fake KENN_LLM_ENABLED=1 KENN_LLM_PROVIDER=ollama "KENN_LLM_MODEL=$MODEL" KENN_LLM_CACHE=0)

# run_measure LABEL ARGS... runs one 30-question pass into $OUT/LABEL.json, skipping it if a re-run finds it done.
run_measure() {
  local label="$1"; shift
  local receipt="$OUT/$label.json"
  if [[ -f "$receipt" ]] && ! confirm "$label.json already exists. Run it again (overwrites)?"; then
    note "kept the existing $label.json"
    return 0
  fi
  say "Running $label: 30 questions, 5 to 15 minutes. Leave the Mac alone until it finishes."
  # The harness exits 1 when any row errored; that is a result to keep, not a reason to stop the session.
  if ! (cd "$KENN_ROOT" && env "${STREAM_ENV[@]}" "$PYTHON" tooling/scripts/measure_chat_latency.py --limit 30 \
        --build-manifest "$OUT/manifest.json" --timeout 90 --receipt "$receipt" "$@" 2>&1 | tee "$OUT/$label.log"); then
    warn "$label finished with errors; they are in the receipt and $label.log"
  fi
}

# companion_check WANT_BACKGROUND confirms the companion answers and names the model it will use.
# Its cache and background settings are not exposed over HTTP, so those are recorded as the owner declared them.
companion_check() {
  local health
  until health=$(curl -sf --max-time 5 "$ENDPOINT/api/health"); do
    warn "no companion answering at $ENDPOINT"
    # pause() ignores end of input, so without a terminal this would retry forever.
    [[ -t 0 ]] || { warn "no terminal to wait on; start the companion and re-run"; exit 1; }
    pause "Start it with the settings above, then press Enter to check again."
  done
  printf '%s' "$health" | "$PYTHON" -c 'import json,sys; m=(json.load(sys.stdin).get("subsystems") or {}).get("answer_model"); print("  companion answer model:", m)'
  confirm "Is that $MODEL, started with KENN_LIVE_BACKEND=fake, KENN_LLM_CACHE=0 and KENN_LLM_BACKGROUND=$1?" \
    || { warn "Restart it with those settings first."; companion_check "$1"; }
}

banner "KENN C1 supervised measurement session"

stage "Preflight"
say "Everything here is read-only against Live. Outputs go to:"
note "$OUT"
power=$(pmset -g batt 2>/dev/null | head -n1 || true)
say "Power: ${power:-unknown}"
[[ "$power" == *"AC Power"* ]] || warn "Plug in first: the 4 and 5 Oct runs on battery gave unusable timings."
git -C "$KENN_ROOT" fetch -q origin main 2>/dev/null || warn "could not fetch; check the checkout is current by hand"
say "Checkout: $(git -C "$KENN_ROOT" rev-parse --short HEAD) ($(git -C "$KENN_ROOT" rev-list --count HEAD..origin/main 2>/dev/null || echo '?') behind origin/main)"
[[ -z "$(git -C "$KENN_ROOT" status --porcelain -- apps/backend/src/kenn tooling/scripts)" ]] \
  || warn "Uncommitted changes under the measured code; the receipt records a dirty-diff hash, but a clean tree is easier to cite."
[[ -f "$KENN_ROOT/apps/backend/src/kenn/data/index/CURRENT" ]] \
  || warn "No retrieval index in this checkout: every answer would abstain. Run from the main checkout."
curl -sf --max-time 5 "$OLLAMA/api/tags" > "$OUT/ollama-tags.json" || warn "Ollama is not answering at $OLLAMA"
grep -q "\"$MODEL\"" "$OUT/ollama-tags.json" 2>/dev/null || warn "$MODEL is not in Ollama's model list"
if pgrep -f "Ableton Live" >/dev/null 2>&1; then warn "Ableton Live is running. Quit it: stages 3 to 5 are the Live-closed runs."; fi
pause "Fix anything flagged above, then press Enter."

stage "Pin the build"
ask SUPERVISOR "Your name, as the person supervising this session:"
write_env SUPERVISOR "$SUPERVISOR"
"$PYTHON" - "$OUT" "$MODEL" "$SUPERVISOR" <<'PY'
import json, subprocess, sys
out, model, supervisor = sys.argv[1:4]
def sh(*args):
    # A missing command is an unknown field, not a reason to lose the whole manifest.
    try:
        return subprocess.run(args, capture_output=True, text=True).stdout.strip()
    except OSError:
        return ""
try:
    tags = json.load(open(f"{out}/ollama-tags.json"))["models"]
    digest = next((m["digest"] for m in tags if m["name"] == model), None)
except Exception:
    digest = None  # recorded as unknown; the receipt must not claim a digest nobody read
json.dump({"model_name": model, "model_digest": digest, "ollama_version": sh("ollama", "--version") or None,
           "cpu": sh("sysctl", "-n", "machdep.cpu.brand_string") or None,
           "memory_bytes": int(sh("sysctl", "-n", "hw.memsize") or 0) or None,
           "macos": sh("sw_vers", "-productVersion") or None, "supervised_by": supervisor,
           "live_conditions": "per run, in owner-notes.json"},
          open(f"{out}/manifest.json", "w"), indent=1)
print("  model digest:", digest or "UNKNOWN")
PY
ollama ps > "$OUT/ollama-ps-before.txt" 2>&1 || true
say "Model residency now:"; sed 's/^/    /' "$OUT/ollama-ps-before.txt"
MODEL_UNLOADED=no
if confirm "Unload the model so the first stream question is model-cold? (ollama stop; it reloads on the first question)"; then
  ollama stop "$MODEL" >/dev/null 2>&1 && MODEL_UNLOADED=yes || warn "ollama stop failed; run 1 will start model-warm"
fi
write_env MODEL_UNLOADED_BEFORE_RUN1 "$MODEL_UNLOADED"

stage "Stream surface, Live closed (4 runs)"
say "In-process runs through answer_payload_stream. Quit the KENN companion for these, so nothing else calls Ollama."
if curl -sf --max-time 3 "$ENDPOINT/api/health" >/dev/null 2>&1; then warn "The companion is still answering at $ENDPOINT."; fi
pause "Companion and Live both quit? Press Enter to start."
# Cold drops KENN's semantic answer cache before every question; warm keeps it, so warm shows what a repeat costs.
run_measure stream-cold-1 --surface stream --cache-condition cold
run_measure stream-cold-2 --surface stream --cache-condition cold
run_measure stream-warm-1 --surface stream --cache-condition warm
run_measure stream-warm-2 --surface stream --cache-condition warm

stage "Foreground HTTP, Live closed (2 runs)"
say "Start the companion yourself, with these set in its environment:"
step "KENN_LIVE_BACKEND=fake KENN_LLM_CACHE=0 KENN_LLM_BACKGROUND=0"
note "With background on, /api/ask answers without the model, so this run would measure templates only."
companion_check 0
# HTTP runs cannot clear the companion's semantic cache, so they are declared warm; the receipt says unverified.
run_measure foreground-1 --surface foreground --endpoint "$ENDPOINT" --cache-condition warm
run_measure foreground-2 --surface foreground --endpoint "$ENDPOINT" --cache-condition warm

stage "Background HTTP, Live closed (2 runs)"
say "Restart the companion with:"
step "KENN_LIVE_BACKEND=fake KENN_LLM_CACHE=0 KENN_LLM_BACKGROUND=1"
companion_check 1
run_measure background-1 --surface background --endpoint "$ENDPOINT" --cache-condition warm
run_measure background-2 --surface background --endpoint "$ENDPOINT" --cache-condition warm

stage "Live open (1 run)"
say "Same companion (KENN_LIVE_BACKEND=fake keeps KENN from touching Live), now with Live open."
step "Open Ableton Live with the set you will use for every future Live-open comparison."
step "Set the audio buffer in Live's Audio preferences, and note it and the sample rate."
step "Start playback yourself and loop a section, so a dropout would be audible."
ask LIVE_SET "Name of the Live set:"
ask LIVE_BUFFER "Buffer size (samples):"
ask LIVE_RATE "Sample rate (Hz):"
write_env LIVE_SET "$LIVE_SET"; write_env LIVE_BUFFER "$LIVE_BUFFER"; write_env LIVE_RATE "$LIVE_RATE"
companion_check 1
run_measure live-open-background-1 --surface background --endpoint "$ENDPOINT" --cache-condition warm
say "Nothing in the harness can see Live's audio engine, so this count is yours."
ask DROPOUTS "Dropouts or clicks you heard during the run (a number, or 'unknown' if you were not listening throughout):"
ask OWNER_NOTE "Anything else worth recording (heat, fans, other apps, oddities)? Enter for none:"
write_env DROPOUTS "$DROPOUTS"; write_env OWNER_NOTE "$OWNER_NOTE"

stage "Wrap up"
ollama ps > "$OUT/ollama-ps-after.txt" 2>&1 || true
SUPERVISOR="$SUPERVISOR" LIVE_SET="$LIVE_SET" LIVE_BUFFER="$LIVE_BUFFER" LIVE_RATE="$LIVE_RATE" DROPOUTS="$DROPOUTS" \
OWNER_NOTE="$OWNER_NOTE" MODEL_UNLOADED="$MODEL_UNLOADED" "$PYTHON" - "$OUT" <<'PY'
import glob, json, os, sys
out = sys.argv[1]
closed = {"live_open": False, "audio_dropouts": None}
notes = {"supervised_by": os.environ["SUPERVISOR"], "model_unloaded_before_stream_cold_1": os.environ["MODEL_UNLOADED"] == "yes",
         "owner_note": os.environ["OWNER_NOTE"] or None, "runs": {}}
for path in sorted(glob.glob(f"{out}/*.json")):
    name = os.path.basename(path)[:-5]
    if name in {"manifest", "ollama-tags", "owner-notes"}:
        continue
    report = json.load(open(path))
    c, s = report["counts"], report["seconds"]
    swaps = [r["swap_bytes"] for r in report["rows"] if r.get("swap_bytes") is not None]
    pressure = sorted({r["memory_pressure"] for r in report["rows"] if r.get("memory_pressure")})
    # Median decode rate over calls that report both halves. A fanless Air fell from about 29 to 20 tok/s mid-session
    # in the 11 Oct v4 bench; watching this per run is how a throttled run gets spotted instead of a fixed cool-down.
    rates = sorted(call["completion_tokens"] / (call["eval_duration_ns"] / 1e9)
                   for row in report["rows"] for call in row.get("provider_calls") or []
                   if call.get("completion_tokens") and call.get("eval_duration_ns"))
    decode = f"{rates[len(rates) // 2]:.1f}" if rates else "?"
    print(f"  {name:24} delivery {c.get('delivery')}  accepted<=15s {c['eligible_accepted_within_15_seconds']}/{c['eligible']}"
          f"  median {s['all_median']}s  ttft {s.get('ttft_median')}s"
          f"  decode {decode} tok/s  swap {min(swaps) if swaps else '?'}..{max(swaps) if swaps else '?'} B  pressure {pressure or '?'}")
    notes["runs"][name] = ({"live_open": True, "live_set": os.environ["LIVE_SET"], "buffer_samples": os.environ["LIVE_BUFFER"],
                            "sample_rate_hz": os.environ["LIVE_RATE"], "audio_dropouts": os.environ["DROPOUTS"]}
                           if name.startswith("live-open") else closed)
json.dump(notes, open(f"{out}/owner-notes.json", "w"), indent=1)
PY
say "Send the folder above to the next session (or commit the receipts as evidence); the C1 note will be written from it."
note "Receipts hold no answer text; keep any --capture-answers files out of git."
pause "Press Enter to finish."

finish
